<?php
if (($_GET['key'] ?? '') !== 'import_clean_db_7789') {
    die("Acesso negado.");
}
require_once __DIR__ . '/gestor/conexao.php';
if (!isset($conn) || !$conn) {
    die("Erro ao obter conexao PDO.");
}
try {
    $sql = base64_decode('');
    $conn->exec($sql);
    $cCad = $conn->query("SELECT COUNT(*) FROM cadastro")->fetchColumn();
    $cUsr = $conn->query("SELECT COUNT(*) FROM usuarios")->fetchColumn();
    header("Content-Type: application/json");
    echo json_encode([
        'status' => 'success',
        'message' => 'Importacao realizada com sucesso!',
        'total_cadastro' => $cCad,
        'total_usuarios' => $cUsr
    ]);
} catch (Exception $e) {
    header("Content-Type: application/json");
    echo json_encode([
        'status' => 'error',
        'message' => $e->getMessage()
    ]);
}
